// Composition follows the approved Home: ring left, live plant right, centered
// register control, then one next action. Empty-state values stay real, never demo data.
export function Home({params = {}}: Partial<ScreenProps>) {
  const {state} = useApp();
  const nav = useNav();
  const {width, fontScale} = useWindowDimensions();
  const {c} = useTheme();
  const calories = dayNutrition(state, state.selectedDate);
  const goal = goalAt(state, state.selectedDate);
  const garden = state.garden;
  const week = garden?.creditedWeeks ?? 0;
  const active = state.sessions.find(s => s.status === 'active' || s.status === 'paused');
  const plan = state.plans[0];
  const collapsed = width < 370 || fontScale > 1.3;
  const macros = [
    {label: 'P', key: 'protein' as const, color: c.protein},
    {label: 'C', key: 'carbs' as const, color: c.carbs},
    {label: 'G', key: 'fat' as const, color: c.fat},
  ];
  return <Screen back={false} dock={false} tab="home" background testID="SC-07">
    <View style={[layout.between, {paddingTop: 10, alignItems: 'flex-start'}]}>
      <View style={{flex: 1}}>
        <Txt size={26}>Buenos días{state.profile.name ? ',' : ''}</Txt>
        {state.profile.name && <Txt size={34} weight="600">{state.profile.name}</Txt>}
        <Txt tone="secondary" size={13} style={{marginTop: 8}}>Disciplina hoy,{"\n"}un mejor mañana.</Txt>
      </View>
      <Pressable accessibilityRole="button" accessibilityLabel="Abrir perfil y ajustes" onPress={() => nav.go('SC-68')}
        style={{width: 44, height: 44, borderRadius: 22, borderWidth: 1, borderColor: c.line,
          backgroundColor: c.surface, alignItems: 'center', justifyContent: 'center'}}>
        <Txt weight="500" size={14}>{state.profile.name ? state.profile.name.slice(0,2).toUpperCase() : 'Vos'}</Txt>
      </Pressable>
    </View>
    <View testID="home-hero" style={{flexDirection: collapsed ? 'column' : 'row', gap: 12,
      alignItems: collapsed ? 'stretch' : 'flex-start', minHeight: collapsed ? undefined : garden ? 244 : 258,
      marginTop: 14}}>
      <View style={{flex: collapsed ? undefined : 1, gap: 12, alignItems: collapsed ? 'center' : 'flex-start'}}>
        <Pressable accessibilityRole="button" accessibilityLabel="Abrir diario de nutrición" onPress={() => nav.go('SC-08')}
          style={{flexDirection: 'row', alignItems: 'center', gap: 6, minHeight: 44}}>
          <Icon name="nutrition" color={c.text} size={17}/><Txt size={12}>Nutrición de hoy</Txt><Icon name="chevron" size={13}/>
        </Pressable>
        {state.profile.showCalories ? <Ring value={calories.energy} goal={goal?.energy} size={Math.min(148,(width-40)*.415)}/>
          : <Txt size={20} weight="600">Tu diario, sin calorías</Txt>}
        <View style={{flexDirection: 'row', gap: 8, flexWrap: 'wrap', marginTop: 1}}>
          {macros.map(m => {
            const value=calories[m.key], target=goal?.[m.key];
            const ratio=value!==null && target!=null && target>0 ? Math.min(1,Math.max(0,value/target)) : 0;
            return <View key={m.key} style={{minWidth: 43, gap: 6}}>
              <Txt size={11.5}>{m.label} {fmt(value)} g</Txt>
              <View accessible={true} accessibilityRole="progressbar" accessibilityLabel={`${m.label}: ${value===null?'sin datos':fmt(value)+' gramos'}${target?' de '+fmt(target):', sin meta configurada'}`}
                accessibilityValue={target && value!==null ? {min:0,max:target,now:Math.min(value,target)} : undefined}
                style={{width:40,height:4,borderRadius:4,backgroundColor:c.line,overflow:'hidden'}}>
                <View style={{width:`${ratio*100}%`,height:4,backgroundColor:m.color,borderRadius:4}}/>
              </View>
            </View>;
          })}
        </View>
      </View>
      {!state.profile.hideGarden && <View style={{flex:collapsed?undefined:1.08,alignItems:'center',
        minHeight:collapsed?undefined:244,overflow:'visible'}}>
        <View pointerEvents="none" style={collapsed ? {width:'100%',height:286} :
          {position:'absolute',top:-82,left:-10,right:-8,height:310}}>
          <Plant seed={garden?.plant.seed??state.localPlantSeed} weeks={week} height={collapsed?286:310}/>
        </View>
        <Pressable accessibilityRole="button" accessibilityLabel="Ver tu jardín" onPress={() => nav.go('SC-79')}
          style={{alignSelf:'stretch',gap:7,marginTop:collapsed?0:150,minHeight:80}}>
          <View style={[layout.row,{gap:7}]}><Icon name="leaf" color={c.protein} size={17}/><Txt size={14}>Tu planta</Txt></View>
          <Txt size={12} tone="secondary">{garden?`Semana ${week} de 52`:'Tu historia empieza con una semilla'}</Txt>
          <View style={{height:6,borderRadius:6,backgroundColor:c.line,overflow:'hidden'}}>
            <View style={{height:6,width:`${week/52*100}%`,backgroundColor:c.protein,borderRadius:6}}/>
          </View>
          <Txt size={11} tone="secondary">{garden?.state==='interrupted'?'Tu planta se conserva. Podés empezar otro ciclo.':garden?
            '1 entrenamiento esta semana mantiene tu crecimiento.':'Plantá tu primer ciclo cuando estés listo.'}</Txt>
        </Pressable>
      </View>}
    </View>
    <Button title="Registrar +" icon="plus" onPress={() => nav.register({date:state.selectedDate})} testID="home-register"
      style={{alignSelf:'center',width:collapsed?'100%':'70%',minWidth:220,marginTop:0,marginBottom:4}}/>
    <View style={{borderTopWidth:StyleSheet.hairlineWidth,borderTopColor:c.line,paddingTop:20,gap:10}}>
      <View style={layout.row}><Icon name="train" size={18}/><Txt size={13} tone="secondary">{active?'Sesión en curso':'Siguiente entrenamiento'}</Txt></View>
      <Txt size={25} weight="600">{active?active.name:plan?plan.days[0]?.name??plan.name:'Construí tu rutina'}</Txt>
      <Txt size={13} tone="secondary">{active?`${active.exercises.length} ejercicios · tus series están guardadas`:plan?
        `${plan.days[0]?.exercises.length??0} ejercicios · plan manual`:'Elegí ejercicios, series y días a tu medida.'}</Txt>
      <Button title={active?'Reanudar sesión':plan?'Ver rutina':'Crear rutina'} icon="arrow" variant="secondary"
        onPress={() => active?nav.go(active.restDeadline?'SC-48':'SC-47',{id:active.id}):plan?nav.go('SC-42',{planId:plan.id}):nav.go('SC-44')}
        style={{alignSelf:'flex-start'}}/>
    </View>
    <View style={layout.wrap}><Button title="Diario" variant="quiet" onPress={() => nav.go('SC-08')}/>
      <Button title="Mi semana" variant="quiet" onPress={() => nav.go('SC-36')}/>
      {!goal&&<Button title="Configurar metas opcionales" variant="quiet" onPress={() => nav.go('SC-04')}/>}</View>
  </Screen>;
}

// Small deterministic production texture: soil is an actual shaded 3D surface,
// not a photograph of a whole plant. No external assets or random per-frame noise.
function soilTexture(seed:number){
 const size=128,data=new Uint8Array(size*size*4);
 for(let y=0;y<size;y++)for(let x=0;x<size;x++){
  const noise=Math.sin(x*12.9898+y*78.233+(seed%997))*43758.5453;
  const grain=noise-Math.floor(noise);
  const clump=(Math.sin(x*.24+Math.sin(y*.16))*Math.cos(y*.23+x*.03)+1)*.5;
  const fibre=grain>.965?1:0;
  const i=(y*size+x)*4;
  data[i]=12+clump*22+grain*8+fibre*32;
  data[i+1]=9+clump*12+grain*5+fibre*20;
  data[i+2]=6+clump*5+grain*3+fibre*9;data[i+3]=255;
 }
 const texture=new THREE.DataTexture(data,size,size,THREE.RGBAFormat);
 texture.colorSpace=THREE.SRGBColorSpace;texture.wrapS=texture.wrapT=THREE.RepeatWrapping;
 texture.repeat.set(3,2);texture.magFilter=THREE.LinearFilter;texture.needsUpdate=true;
 return texture;
}
function Object3D({descriptor,week,animated}:{descriptor:PlantDescriptor;week:number;animated:boolean}){const group=useRef<THREE.Group>(null);const texture=useMemo(()=>leafTexture(descriptor.seed),[descriptor.seed]);const soilMap=useMemo(()=>soilTexture(descriptor.seed),[descriptor.seed]);useEffect(()=>()=>{texture.dispose();soilMap.dispose()},[texture,soilMap]);useFrame(({clock})=>{if(group.current&&animated)group.current.rotation.y=Math.sin(clock.elapsedTime*.35)*.012});const pot=useMemo(()=>new THREE.LatheGeometry([new THREE.Vector2(.27,-.59),new THREE.Vector2(.33,-.53),new THREE.Vector2(.375,-.34),new THREE.Vector2(.36,-.06),new THREE.Vector2(.33,.075),new THREE.Vector2(.315,.075),new THREE.Vector2(.345,-.06),new THREE.Vector2(.36,-.34),new THREE.Vector2(.315,-.51),new THREE.Vector2(.27,-.56)],48),[]);const soil=useMemo(()=>new THREE.LatheGeometry([new THREE.Vector2(0,-.53),new THREE.Vector2(.275,-.53),new THREE.Vector2(.345,-.32),new THREE.Vector2(.33,-.05),new THREE.Vector2(.315,.025),new THREE.Vector2(0,.025)],32),[]);useEffect(()=>()=>{pot.dispose();soil.dispose()},[pot,soil]);const roots=useMemo(()=>descriptor.roots.map(r=>Array.from({length:7},(_,i)=>{const t=i/6,ang=r.angle+Math.sin(t*6+r.phase)*.15;const radius=.327+Math.sin(t*Math.PI)*.026;return new THREE.Vector3(Math.sin(ang)*radius,.02-t*.54*Math.min(1,week/18),Math.cos(ang)*radius)})),[descriptor,week]);return <group ref={group} rotation={[0,-.28,0]}>
 <mesh geometry={soil}><meshStandardMaterial map={soilMap} color="#B8A691" roughness={.98}/></mesh>
 {week>0&&roots.slice(0,Math.min(36,4+Math.floor(week*.62))).map((points,i)=><Tube key={i} points={points} radius={descriptor.roots[i].width} color={i%4?'#493622':'#806641'}/>)}
 <mesh geometry={pot} renderOrder={2}><meshPhysicalMaterial color="#DEE6DE" roughness={.075} metalness={0} transparent opacity={.10} clearcoat={1} clearcoatRoughness={.04} side={THREE.FrontSide} depthWrite={false}/></mesh>
 <mesh position={[0,.075,0]} rotation={[Math.PI/2,0,0]}><torusGeometry args={[.323,.007,8,48]}/><meshPhysicalMaterial color="#E2E8DF" metalness={.5} roughness={.16}/></mesh>
 {Array.from({length:26},(_,i)=><mesh key={'moss'+i} position={[Math.sin(i*2.4)*(.10+i%4*.04),.026+Math.sin(i)*.007,Math.cos(i*2.4)*(.10+i%4*.04)]} scale={[.023,.009,.018]}><sphereGeometry args={[1,6,4]}/><meshStandardMaterial color={i%3===0?'#556229':'#333B15'} roughness={1}/></mesh>)}
 {week===0?<mesh position={[0,.055,0]} rotation={[.2,.3,.9]} scale={[.03,.055,.027]}><sphereGeometry args={[1,12,8]}/><meshStandardMaterial color="#705031" roughness={.7}/></mesh>:descriptor.leaves.map(d=><Leaf key={d.id} d={d} week={week} texture={texture}/>)}
 </group>}

test('Home preserves real empty data, contextual logging and optional goals without invented progress',()=>{
 show(<Home/>);
 expect(screen.getByText('Tu historia empieza con una semilla')).toBeTruthy();
 expect(screen.queryByText('Semana 18 de 52')).toBeNull();
 const bars=screen.getAllByRole('progressbar');
 expect(bars).toHaveLength(3);for(const bar of bars)expect(bar.props.accessibilityValue).toBeUndefined();
 fireEvent.press(screen.getByTestId('home-register'));
 expect(navigation.router.push).toHaveBeenCalledWith(expect.objectContaining({pathname:'/register'}));
 fireEvent.press(screen.getByRole('button',{name:'Configurar metas opcionales'}));
 expect(navigation.router.push).toHaveBeenLastCalledWith(expect.objectContaining({params:expect.objectContaining({screenId:'SC-04'})}));
});
test('Home macro progress uses actual amounts and the effective goal, not decorative filled bars',async()=>{
 await repo.dispatch({type:'goal',goal:{id:'home-goal',version:1,effectiveFrom:repo.getSnapshot().selectedDate,energy:2000,protein:150,carbs:200,fat:60}});
 show(<Home/>);
 const bars=screen.getAllByRole('progressbar');expect(bars.map(b=>b.props.accessibilityValue.now)).toEqual([0,0,0]);
 expect(bars.map(b=>b.props.accessibilityValue.max)).toEqual([150,200,60]);
 expect(screen.queryByRole('button',{name:'Configurar metas opcionales'})).toBeNull();
});
